//! Golden-file checks of the Format 1.6 storage features (ACE 0.8.0).
//!
//! `examples/golden/0.8.0/GOLDEN.json` pins, for six inputs that use columnar blocks, segments and
//! preset dictionaries, the SHA-256 and size of the container every profile writes. The
//! 0.6.1 golden file (`golden.rs`) pins the bytes of the unchanged paths; this one pins the new
//! ones, and it is the reference that the C ABI, the Java SDK and the Scala SDK reproduce.
//!
//! The file is flat on purpose (scalars only), so that any binding can read it with a few lines of
//! code. The inputs are generated by [`input`]; the same generators, written again in C-ABI,
//! Java and Scala tests, must produce the same bytes. A dictionary is trained from the first 300
//! JSON records with `TrainerConfig { dictionary_size: 2048, segment_len: 64, .. }`, which is what
//! `ace::Dictionary::train` and `ace_dictionary_train` do.
//!
//! * `ACE_GOLDEN_UPDATE=1 cargo test -p ace-engine --test golden_storage` rewrites the file (only
//!   for an intentional, documented change of the bytes of Format 1.6).
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)] // test code: a panic is a failing test

use std::path::PathBuf;
use std::sync::Arc;

use ace_core::{
    AceConfig, ColumnKind, ColumnSpec, CompressionProfile, DictionaryScope, EncoderDictionary,
    Schema, SegmentationConfig,
};
use ace_corpus::RecordWorkload;
use ace_dictionary::{
    dictionary_id_of, train_dictionary, Dictionary, DictionaryRegistry, TrainerConfig,
};
use ace_engine::AceEngine;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

/// Profiles of the file, in the order of the fields.
const PROFILES: [(&str, CompressionProfile); 3] = [
    ("fast", CompressionProfile::Fast),
    ("balanced", CompressionProfile::Balanced),
    ("dense", CompressionProfile::Dense),
];

/// One case: name, generator, block size, schema, smallest segment (0 = no segmentation),
/// dictionary (`none`, `embedded`, `external`).
type Spec = (
    &'static str,
    &'static str,
    usize,
    &'static str,
    usize,
    &'static str,
);

/// The cases of the file. Never change one; add a new case.
const SPECS: [Spec; 6] = [
    (
        "columnar-trades",
        "records-trades:1048576",
        262_144,
        "u8,f8,u4,b4",
        0,
        "none",
    ),
    (
        "columnar-telemetry",
        "records-telemetry:1048576",
        262_144,
        "u2,u1,u1,u4,f4,u4",
        0,
        "none",
    ),
    (
        "columnar-events",
        "records-events:1048576",
        262_144,
        "u8,u1,u8,b15",
        0,
        "none",
    ),
    (
        "segmented-mixed",
        "mixed-regimes",
        4 << 20,
        "",
        131_072,
        "none",
    ),
    (
        "dictionary-embedded",
        "json-records:600",
        4096,
        "",
        0,
        "embedded",
    ),
    (
        "dictionary-external",
        "json-records:600",
        4096,
        "",
        0,
        "external",
    ),
];

/// Root document.
#[derive(Debug, PartialEq, Serialize, Deserialize)]
struct GoldenFile {
    /// Document schema identifier.
    schema: String,
    /// Milestone that produced the hashes.
    milestone: String,
    /// The cases, in [`SPECS`] order.
    cases: Vec<Case>,
}

/// Settings and hashes of one case. Every member is a scalar.
#[derive(Debug, PartialEq, Serialize, Deserialize)]
struct Case {
    case: String,
    generator: String,
    block_size: usize,
    /// Record layout as `u8,f8,..` (`u` unsigned, `s` signed, `f` float, `b` bytes + width); empty for none.
    schema: String,
    /// Smallest segment in bytes; 0 means segmentation is off.
    segmentation_min: usize,
    /// `none`, `embedded` or `external`.
    dictionary: String,
    /// Id of the trained dictionary in hex; empty for none.
    dictionary_id: String,
    /// SHA-256 of the trained dictionary; empty for none.
    dictionary_sha256: String,
    input_bytes: usize,
    input_sha256: String,
    fast_sha256: String,
    fast_bytes: usize,
    balanced_sha256: String,
    balanced_bytes: usize,
    dense_sha256: String,
    dense_bytes: usize,
    /// Format minor version of the files (6 for all of them).
    format_minor: u8,
    /// Blocks per kind in the `balanced` file.
    columnar_blocks: u64,
    segmented_blocks: u64,
    dictionary_blocks: u64,
    decoded_sha256: String,
}

/// Lower-case hex SHA-256.
fn sha256(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

/// `examples/golden/0.8.0/GOLDEN.json`.
fn golden_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../examples/golden/0.8.0/GOLDEN.json")
}

/// One JSON record of the dictionary cases (also written in the other bindings' tests).
fn json_record(i: usize) -> Vec<u8> {
    format!(
        "{{\"sensor\":\"temperature_reading\",\"unit\":\"celsius\",\"site\":\"plant-{}\",\"value\":{}}}\n",
        i % 7,
        1000 + i * 13 % 97
    )
    .into_bytes()
}

/// The input a generator name stands for.
fn input(generator: &str) -> Vec<u8> {
    if let Some(bytes) = generator.strip_prefix("records-") {
        let (name, size) = bytes.split_once(':').unwrap();
        let workload = RecordWorkload::from_name(&format!("records-{name}")).unwrap();
        return workload.generate(size.parse().unwrap());
    }
    if let Some(count) = generator.strip_prefix("json-records:") {
        return (0..count.parse().unwrap()).flat_map(json_record).collect();
    }
    assert_eq!(generator, "mixed-regimes");
    // 400 000 little-endian counters that step every other value, then 1.5 MB of cheap noise.
    let mut out: Vec<u8> = (0..400_000u32)
        .flat_map(|i| (i / 2).to_le_bytes())
        .collect();
    out.extend((0..1_500_000u64).map(|i| (i.wrapping_mul(2_654_435_761) >> 13) as u8));
    out
}

/// The schema a layout string stands for.
fn schema(layout: &str) -> Option<Schema> {
    if layout.is_empty() {
        return None;
    }
    let columns = layout
        .split(',')
        .map(|column| {
            let kind = match &column[..1] {
                "u" => ColumnKind::Unsigned,
                "s" => ColumnKind::Signed,
                "f" => ColumnKind::Float,
                "b" => ColumnKind::Bytes,
                other => panic!("column kind {other}"),
            };
            ColumnSpec {
                width: column[1..].parse().unwrap(),
                kind,
            }
        })
        .collect();
    Some(Schema::new(columns).unwrap())
}

/// The dictionary trained from the first 300 records.
fn trained() -> EncoderDictionary {
    let samples: Vec<Vec<u8>> = (0..300).map(json_record).collect();
    let borrowed: Vec<&[u8]> = samples.iter().map(Vec::as_slice).collect();
    let config = TrainerConfig {
        dictionary_size: 2048,
        segment_len: 64,
        ..TrainerConfig::default()
    };
    let bytes = train_dictionary(&borrowed, &config).unwrap();
    EncoderDictionary {
        id: dictionary_id_of(&bytes),
        scope: DictionaryScope::File,
        bytes: Arc::from(bytes),
    }
}

/// Computes the case of `spec` with the current encoder.
fn compute(spec: &Spec) -> Case {
    let (name, generator, block_size, layout, segmentation_min, dictionary_kind) = *spec;
    let data = input(generator);
    let trained = (dictionary_kind != "none").then(trained);
    let dictionary = trained.as_ref().map(|dictionary| EncoderDictionary {
        scope: if dictionary_kind == "external" {
            DictionaryScope::External
        } else {
            DictionaryScope::File
        },
        ..dictionary.clone()
    });
    let mut registry = DictionaryRegistry::new();
    if let Some(dictionary) = &dictionary {
        registry.insert(Dictionary::new(
            dictionary.id,
            DictionaryScope::External,
            dictionary.bytes.to_vec(),
        ));
    }
    let mut hashes = Vec::new();
    let mut balanced_stats = None;
    let mut format_minor = 0;
    for (profile_name, profile) in PROFILES {
        let engine = AceEngine::new(AceConfig {
            block_size,
            profile,
            schema: schema(layout),
            segmentation: (segmentation_min > 0).then(|| SegmentationConfig {
                min_segment_size: segmentation_min,
                ..SegmentationConfig::default()
            }),
            dictionary: dictionary.clone(),
            ..AceConfig::default()
        })
        .unwrap()
        .with_dictionaries(registry.clone());
        let (file, stats) = engine.compress_with_stats(&data).unwrap();
        assert_eq!(
            engine.decompress(&file).unwrap(),
            data,
            "{name} {profile_name}"
        );
        format_minor = file[5];
        hashes.push((sha256(&file), file.len()));
        if profile_name == "balanced" {
            balanced_stats = Some(stats);
        }
    }
    let stats = balanced_stats.unwrap();
    Case {
        case: name.to_owned(),
        generator: generator.to_owned(),
        block_size,
        schema: layout.to_owned(),
        segmentation_min,
        dictionary: dictionary_kind.to_owned(),
        dictionary_id: trained
            .as_ref()
            .map_or_else(String::new, |d| format!("{:016x}", d.id.0)),
        dictionary_sha256: trained
            .as_ref()
            .map_or_else(String::new, |d| sha256(&d.bytes)),
        input_bytes: data.len(),
        input_sha256: sha256(&data),
        fast_sha256: hashes[0].0.clone(),
        fast_bytes: hashes[0].1,
        balanced_sha256: hashes[1].0.clone(),
        balanced_bytes: hashes[1].1,
        dense_sha256: hashes[2].0.clone(),
        dense_bytes: hashes[2].1,
        format_minor,
        columnar_blocks: stats.columnar_blocks,
        segmented_blocks: stats.segmented_blocks,
        dictionary_blocks: stats.dictionary_blocks,
        decoded_sha256: sha256(&data),
    }
}

/// All cases.
fn compute_all() -> GoldenFile {
    GoldenFile {
        schema: "ace-golden-storage-1".to_owned(),
        milestone: "0.8.0".to_owned(),
        cases: SPECS.iter().map(compute).collect(),
    }
}

/// The encoder writes the committed bytes.
#[test]
fn storage_golden_hashes_match() {
    let actual = compute_all();
    let path = golden_path();
    if std::env::var("ACE_GOLDEN_UPDATE").is_ok_and(|value| value == "1") {
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(&path, serde_json::to_string_pretty(&actual).unwrap() + "\n").unwrap();
        return;
    }
    let committed: GoldenFile = serde_json::from_str(&std::fs::read_to_string(&path).unwrap())
        .unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    assert_eq!(
        actual, committed,
        "a Format 1.6 byte changed: if intended, run with ACE_GOLDEN_UPDATE=1 and document it"
    );
}

/// Each case really uses the feature it exists for, and every file is Format 1.6.
#[test]
fn every_case_uses_its_feature() {
    let committed: GoldenFile =
        serde_json::from_str(&std::fs::read_to_string(golden_path()).unwrap()).unwrap();
    assert_eq!(committed.cases.len(), SPECS.len());
    for case in &committed.cases {
        assert_eq!(case.format_minor, 6, "{}", case.case);
        match case.case.split('-').next().unwrap() {
            "columnar" => assert!(case.columnar_blocks > 0, "{}", case.case),
            "segmented" => assert!(case.segmented_blocks > 0, "{}", case.case),
            "dictionary" => assert!(case.dictionary_blocks > 0, "{}", case.case),
            other => panic!("unknown case kind {other}"),
        }
        assert_eq!(case.input_sha256, case.decoded_sha256);
    }
}
